}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    ptr_t ret = 0;
    int best_class = 4;

    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL) {
            continue;
        }

        PTE *pgtable = user_page[i].pgtable;
        if (!get_attribute(*pgtable, _PAGE_PRESENT)) {
            continue;
        }

        int accessed = get_attribute(*pgtable, _PAGE_ACCESSED);
        int dirty = get_attribute(*pgtable, _PAGE_DIRTY);
        int page_class = (accessed ? 2 : 0) + (dirty ? 1 : 0);

        if (page_class < best_class) {
            best_class = page_class;
            ret = num2pa(i);
            if (best_class == 0) {
                break;
            }
        }

        if (accessed) {
            clear_attribute(pgtable, _PAGE_ACCESSED);
        }
    }

    assert(ret != 0);
    return ret;
}

void write_to_sd(ptr_t pa)
{
    int slot = -1;
    for (int i = 0; i < DISK_PAGE_NUM; i++) {
        if (disk_page[i].valid == 0) {
            slot = i;
            break;
        }
    }

    assert(slot != -1);
    sbi_sd_write(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));

    PTE *pgtable = user_page[pa2num(pa)].pgtable;
    assert(pgtable != NULL);
    *pgtable = 0;
    set_pfn(pgtable, slot);
    set_attribute(pgtable, _PAGE_SOFT);
    disk_page[slot].valid = 1;
    free_user_page(pa);
    local_flush_tlb_all();
}

unsigned long free_page_num()
{
    unsigned long ret = 0;
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            ret++;
        }
    }
    return ret;
}

/*
 * Virtual Memory Layout
 * 0x0_0000_1000 ~ 0x0_0001_0000: share
 * 0x0_0001_0000 ~ 0x0_0001_3000: code
 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
 */
PTE* init_page_table()
{
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
    pgdir_kva[0x101] = kernel_pgdir[0x101];

    PTE *low_second_level = alloc_pgdir_page();
    set_pfn(pgdir_kva + 0, (uint64_t)low_second_level >> NORMAL_PAGE_SHIFT);
    set_attribute(pgdir_kva + 0, _PAGE_PRESENT);

    PTE *low_second_level_kva = (PTE *)pa2kva((uintptr_t)low_second_level);
    PTE *low_last_level = alloc_pgdir_page();
    set_pfn(low_second_level_kva + 0,
            (uint64_t)low_last_level >> NORMAL_PAGE_SHIFT);
    set_attribute(low_second_level_kva + 0, _PAGE_PRESENT);

    PTE *low_last_level_kva = (PTE *)pa2kva((uintptr_t)low_last_level);
    for (int i = 0x10; i <= 0x12; i++) {
        ptr_t pa = alloc_user_page(0, low_last_level_kva + i);
        map_leaf_page(low_last_level_kva + i, pa);
    }

    PTE *stack_second_level = alloc_pgdir_page();
    set_pfn(pgdir_kva + 0x3c,
            (uint64_t)stack_second_level >> NORMAL_PAGE_SHIFT);
    set_attribute(pgdir_kva + 0x3c, _PAGE_PRESENT);

    PTE *stack_second_level_kva = (PTE *)pa2kva((uintptr_t)stack_second_level);
    PTE *stack_last_level = alloc_pgdir_page();
    set_pfn(stack_second_level_kva + 0,
            (uint64_t)stack_last_level >> NORMAL_PAGE_SHIFT);
    set_attribute(stack_second_level_kva + 0, _PAGE_PRESENT);

    PTE *stack_last_level_kva = (PTE *)pa2kva((uintptr_t)stack_last_level);
    ptr_t stack_pa = alloc_user_page(0, stack_last_level_kva + 0xf);
    map_leaf_page(stack_last_level_kva + 0xf, stack_pa);

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    if (pgdir == NULL || pgdir == (PTE *)PGDIR_PA) {
