// sleep(seconds)
void do_sleep(uint32_t sleep_time)
{
    // 1. block the current_running
    // 2. create a timer which calls `do_unblock` when timeout
    // 3. reschedule because the current_running is blocked
    do_block(&current_running[cpu_id]->list, &sleep_queue);
    list_node_t* parameter = &current_running[cpu_id]->list;
    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
    scheduler();
}

int do_kill(pid_t pid)
{
    pcb_t *killed_pcb = NULL;

    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            killed_pcb = &pcb[i];
            break;
        }
    }
    if (killed_pcb == NULL || killed_pcb->status == TASK_ZOMBIE) {
        return 0;
    }

    if (killed_pcb->status == TASK_RUNNING) {
        killed_pcb->status = TASK_KILLED;
        return 1;
    }

    enter_zombie(killed_pcb, 1);

    for (list_node_t *node = timer_queue.next; node != &timer_queue;
         node = node->next) {
        if (node == &killed_pcb->timer.list) {
            list_del(node);
            break;
        }
    }

    scheduler();
    return 1;
}

int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
{
    pcb_t *wait_pcb = NULL;

    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            wait_pcb = &pcb[i];
            break;
        }
    }
    if (wait_pcb == NULL) {
        return 0;
    }

    wait_pcb->mode = ENTER_ZOMBIE_ON_EXIT;
    if (wait_pcb->status == TASK_ZOMBIE) {
        list_del(&wait_pcb->list);
        wait_pcb->status = TASK_EXITED;
        wait_pcb->pid = -1;
        free_user_page(kva2pa(wait_pcb->kernel_stack_base - PAGE_SIZE));
        return 1;
    }

    regs->sepc -= 4;
    do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
    scheduler();
    return pid;
}

