+static uint32_t inode_block_count(uint16_t inode_id, const inode_t *inode)
+{
+    uint32_t count = (inode->size + PAGE_SIZE - 1) / PAGE_SIZE;
+    if (count == 0 && inode->mode == DIR) {
+        count = 1;
+    }
