+    for (uint32_t i = 0; i < 10; i++) {
+        if (inode->direct_blocks[i] != 0 ||
+            is_root_block_ref(inode_id, inode, i, inode->direct_blocks[i])) {
+            if (count < i + 1) {
+                count = i + 1;
+            }
+        }
+    }
+
+    for (uint32_t table = 0; table < 2; table++) {
+        if (inode->indirect_blocks[table] == 0) {
+            continue;
+        }
+
+        read_block(inode->indirect_blocks[table]);
+        uint32_t *indirect = (uint32_t *)cached_block_base;
+        for (uint32_t i = 0; i < PAGE_SIZE / sizeof(uint32_t); i++) {
+            if (indirect[i] != 0) {
+                uint32_t logical_idx = 10 + table * (PAGE_SIZE / sizeof(uint32_t)) + i;
+                if (count < logical_idx + 1) {
+                    count = logical_idx + 1;
+                }
+            }
+        }
+    }
