+uint32_t fs_get_data_block(uint16_t inode_id, uint32_t logical_idx, int create)
+{
+    inode_t inode;
+    fs_read_inode_copy(inode_id, &inode);
+
+    if (logical_idx < 10) {
+        uint32_t block_id = inode.direct_blocks[logical_idx];
+        if (block_id == 0 &&
+            !is_root_block_ref(inode_id, &inode, logical_idx, block_id)) {
+            if (!create) {
+                return 0;
+            }
+
+            block_id = alloc_block();
+            if (block_id == 0xffffffff) {
+                return 0xffffffff;
+            }
+            inode.direct_blocks[logical_idx] = block_id;
+            fs_write_inode_copy(inode_id, &inode);
+        }
+        return block_id;
+    }
+
+    if (logical_idx >= 10 + 2 * (PAGE_SIZE / sizeof(uint32_t))) {
+        return 0xffffffff;
+    }
+
+    uint32_t table_idx = logical_idx >= 10 + PAGE_SIZE / sizeof(uint32_t) ? 1 : 0;
+    uint32_t table_block = inode.indirect_blocks[table_idx];
+    if (table_block == 0) {
+        if (!create) {
+            return 0;
+        }
+
+        table_block = alloc_block();
+        if (table_block == 0xffffffff) {
+            return 0xffffffff;
+        }
+        inode.indirect_blocks[table_idx] = table_block;
+        fs_write_inode_copy(inode_id, &inode);
+    }
+
+    uint32_t entry_idx = logical_idx - 10 - table_idx * (PAGE_SIZE / sizeof(uint32_t));
+    read_block(table_block);
+    uint32_t data_block = ((uint32_t *)cached_block_base)[entry_idx];
+    if (data_block == 0 && create) {
+        data_block = alloc_block();
+        if (data_block == 0xffffffff) {
+            return 0xffffffff;
+        }
+        read_block(table_block);
+        ((uint32_t *)cached_block_base)[entry_idx] = data_block;
+        write_block(table_block);
+    }
+
+    return data_block;
+}
