+int fs_resolve_path(const char *path, int want_parent, uint16_t *inode_id,
+                    uint8_t *type, uint32_t *block_id, char *leaf_name)
+{
+    if (path == NULL) {
+        return 0;
+    }
+
+    read_superblock();
+
+    uint16_t cur_inode_id = path[0] == '/' ? superblock->root_inode_id
+                                           : current_dir_inode;
+    inode_t cur_inode;
+    fs_read_inode_copy(cur_inode_id, &cur_inode);
+    uint8_t cur_type = cur_inode.mode;
