+        return 1;
+    }
+
+    int pos = path[0] == '/' ? 1 : 0;
+    while (path[pos] == '/') {
+        pos++;
+    }
+    if (path[pos] == '\0') {
+        if (want_parent) {
+            return 0;
+        }
