+            *inode_id = superblock->root_inode_id;
+        }
+        if (type != NULL) {
+            *type = DIR;
+        }
+        if (block_id != NULL) {
+            *block_id = superblock->root_block_id;
+        }
+        if (leaf_name != NULL) {
+            leaf_name[0] = '\0';
+        }
+        return 1;
+    }
+
+    char component[29];
+    while (1) {
+        int len = 0;
+        while (path[pos] != '\0' && path[pos] != '/') {
+            if (len >= (int)sizeof(component) - 1) {
+                return 0;
+            }
+            component[len++] = path[pos++];
+        }
+        component[len] = '\0';
+        while (path[pos] == '/') {
+            pos++;
+        }
+        int is_last = path[pos] == '\0';
+
+        if (want_parent && is_last) {
+            if (leaf_name != NULL) {
+                strcpy(leaf_name, component);
+            }
+            if (inode_id != NULL) {
+                *inode_id = cur_inode_id;
+            }
+            if (type != NULL) {
+                *type = cur_type;
+            }
+            if (block_id != NULL) {
+                *block_id = cur_inode.direct_blocks[0];
+            }
+            return 1;
+        }
+
+        if (!strcmp(component, ".")) {
+            if (is_last) {
+                break;
+            }
+            continue;
+        }
+
+        dir_entry_t entry;
+        if (!fs_lookup_entry(cur_inode_id, component, &entry, NULL, NULL)) {
+            return 0;
+        }
+        if (!is_last && entry.type != DIR) {
+            return 0;
+        }
+
+        cur_inode_id = entry.inode;
+        cur_type = entry.type;
+        fs_read_inode_copy(cur_inode_id, &cur_inode);
+
+        if (is_last) {
+            if (inode_id != NULL) {
+                *inode_id = cur_inode_id;
+            }
+            if (type != NULL) {
+                *type = cur_type;
+            }
+            if (block_id != NULL) {
+                *block_id = cur_inode.direct_blocks[0];
+            }
+            if (leaf_name != NULL) {
+                leaf_name[0] = '\0';
+            }
+            return 1;
+        }
+    }
+
+    if (want_parent) {
+        return 0;
+    }
+    if (inode_id != NULL) {
+        *inode_id = cur_inode_id;
+    }
+    if (type != NULL) {
+        *type = cur_type;
+    }
+    if (block_id != NULL) {
+        *block_id = cur_inode.direct_blocks[0];
+    }
+    if (leaf_name != NULL) {
+        leaf_name[0] = '\0';
+    }
